// Package session keeps login sessions in Redis.
package session

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"time"
)

// ErrNotFound is returned when a session id is unknown or has expired.
var ErrNotFound = errors.New("session: not found")

// Session is what the store keeps per login.
type Session struct {
	ID        string    `json:"id"`
	UserID    string    `json:"user_id"`
	CreatedAt time.Time `json:"created_at"`
}

// Store reads and writes sessions under a key prefix.
type Store struct {
	rdb    Redis
	prefix string
}

// NewStore returns a store that namespaces its keys with prefix.
func NewStore(rdb Redis, prefix string) *Store {
	return &Store{rdb: rdb, prefix: prefix}
}

func (s *Store) key(id string) string { return s.prefix + ":" + id }

// Load returns the session stored under id, or ErrNotFound.
func (s *Store) Load(ctx context.Context, id string) (Session, error) {
	raw, found, err := s.rdb.Get(ctx, s.key(id))
	if err != nil {
		return Session{}, fmt.Errorf("session: load %s: %w", id, err)
	}
	if !found {
		return Session{}, ErrNotFound
	}
	var sess Session
	if err := json.Unmarshal([]byte(raw), &sess); err != nil {
		return Session{}, fmt.Errorf("session: load %s: %w", id, err)
	}
	return sess, nil
}

// Delete removes the session stored under id. Deleting an unknown id is
// not an error.
func (s *Store) Delete(ctx context.Context, id string) error {
	if err := s.rdb.Del(ctx, s.key(id)); err != nil {
		return fmt.Errorf("session: delete %s: %w", id, err)
	}
	return nil
}

// Redis is the subset of the Redis client the store uses.
type Redis interface {
	Get(ctx context.Context, key string) (value string, found bool, err error)
	SetPX(ctx context.Context, key, value string, ttlMillis int64) error
	PExpire(ctx context.Context, key string, ttlMillis int64) (existed bool, err error)
	Del(ctx context.Context, key string) error
}

// Save writes sess and lets it expire after ttlMillis milliseconds.
func (s *Store) Save(ctx context.Context, sess Session, ttlMillis int64) error {
	if ttlMillis <= 0 {
		return fmt.Errorf("session: save %s: non-positive ttl %dms", sess.ID, ttlMillis)
	}
	raw, err := json.Marshal(sess)
	if err != nil {
		return fmt.Errorf("session: save %s: %w", sess.ID, err)
	}
	if err := s.rdb.SetPX(ctx, s.key(sess.ID), string(raw), ttlMillis); err != nil {
		return fmt.Errorf("session: save %s: %w", sess.ID, err)
	}
	return nil
}

// Touch resets the remaining lifetime of session id to ttlMillis
// milliseconds. It returns ErrNotFound when the session no longer exists.
func (s *Store) Touch(ctx context.Context, id string, ttlMillis int64) error {
	if ttlMillis <= 0 {
		return fmt.Errorf("session: touch %s: non-positive ttl %dms", id, ttlMillis)
	}
	existed, err := s.rdb.PExpire(ctx, s.key(id), ttlMillis)
	if err != nil {
		return fmt.Errorf("session: touch %s: %w", id, err)
	}
	if !existed {
		return ErrNotFound
	}
	return nil
}

