package session

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"time"
)

// Manager issues sessions and keeps them alive while they are used.
type Manager struct {
	store   *Store
	idleTTL int64
	maxHold time.Duration
	now     func() time.Time
}

// NewManager returns a manager whose sessions expire after idle without
// activity. Hold can keep a single session alive for at most maxHold.
func NewManager(store *Store, idle, maxHold time.Duration) (*Manager, error) {
	if store == nil {
		return nil, errors.New("session: nil store")
	}
	if idle < time.Second {
		return nil, fmt.Errorf("session: idle timeout %s is below one second", idle)
	}
	if maxHold < idle {
		return nil, fmt.Errorf("session: max hold %s is below the idle timeout %s", maxHold, idle)
	}
	return &Manager{
		store:   store,
		idleTTL: idle.Milliseconds(),
		maxHold: maxHold,
		now:     time.Now,
	}, nil
}

// Start creates a session for userID.
func (m *Manager) Start(ctx context.Context, userID string) (Session, error) {
	if userID == "" {
		return Session{}, errors.New("session: empty user id")
	}
	id, err := newID()
	if err != nil {
		return Session{}, err
	}
	sess := Session{ID: id, UserID: userID, CreatedAt: m.now().UTC()}
	if err := m.store.Save(ctx, sess, m.idleTTL); err != nil {
		return Session{}, err
	}
	return sess, nil
}

// Resume returns the session for id and restarts its idle timeout.
func (m *Manager) Resume(ctx context.Context, id string) (Session, error) {
	sess, err := m.store.Load(ctx, id)
	if err != nil {
		return Session{}, err
	}
	if err := m.store.Touch(ctx, id, m.idleTTL); err != nil {
		return Session{}, err
	}
	return sess, nil
}

// Hold keeps session id alive for d while a long-running export is in
// progress and no request arrives. d is capped at the manager's maxHold;
// the next Resume returns the session to the idle timeout.
func (m *Manager) Hold(ctx context.Context, id string, d time.Duration) error {
	if d <= 0 {
		return fmt.Errorf("session: hold %s: non-positive duration %s", id, d)
	}
	if d > m.maxHold {
		d = m.maxHold
	}
	return m.store.Touch(ctx, id, int64(d.Seconds()))
}

// End deletes the session. Ending an unknown session is not an error.
func (m *Manager) End(ctx context.Context, id string) error {
	return m.store.Delete(ctx, id)
}

func newID() (string, error) {
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		return "", fmt.Errorf("session: generate id: %w", err)
	}
	return hex.EncodeToString(b[:]), nil
}
